// Worker entry: the Next.js app (built by OpenNext), an edge page cache, and the hourly usage check.
//
// Edge page cache: the Cloudflare free plan allows about 10 ms of CPU per request, and rendering a
// Next.js page can take more. Public store pages are therefore kept at Cloudflare's edge (Cache API)
// and served from there without rendering. A copy is kept per language and per wholesale code, and
// every saved change in the admin panel (and every deploy) starts a fresh set of copies.
// @ts-ignore generated by `opennextjs-cloudflare build`
import { default as app } from "./.open-next/worker.js";
// Load the Next.js server and all its pages at startup (see open-next.config.ts), not in a visitor's request
// @ts-ignore generated by `opennextjs-cloudflare build`
import "./.open-next/server-functions/default/handler.mjs";
import { runUsageAlert } from "./src/lib/usageAlert";

type D1 = { prepare(q: string): { bind(...v: unknown[]): { first<T>(): Promise<T | null>; run(): Promise<unknown> } } };
type R2Object = { body: ReadableStream; size: number; httpMetadata?: { contentType?: string } };
type Env = Parameters<typeof runUsageAlert>[0] & {
  DB: D1;
  BUCKET: { get(key: string): Promise<R2Object | null> };
  CF_VERSION_METADATA?: { id: string };
  MAIN_DOMAIN?: string;
  ADMIN_SESSION_SECRET?: string;
};
type Ctx = { waitUntil(p: Promise<unknown>): void };

const PAGE_TTL = 3 * 3600; // a copy older than this is refreshed in the background (covers offers that start or end by date)
const MISSING_TTL = 600; // "page not found" answers
const KEEP = 7 * 24 * 3600; // how long a copy may be served (refreshed in the background) before it is dropped
const refreshing = new Set<string>(); // background renders in progress in this isolate
const FILE_TTL = 30 * 24 * 3600; // uploaded files never change (each upload gets a new name)
// Pages that depend on a signed-in person or must always be fresh are never cached
const PRIVATE = /^\/(api|admin|admin-login|rep|rep-login|trade|order|_next\/image)(\/|$)/;
// Read-only store data used by the catalog pages (prices depend on language and wholesale code, which are in the key)
const CACHED_API = /^\/api\/(products|products\/by-ids|search|categories)$/;
const TYPES: Record<string, string> = { jpg: "image/jpeg", png: "image/png", webp: "image/webp", gif: "image/gif", pdf: "application/pdf" };
const ROUTER_HEADERS = ["rsc", "next-router-prefetch", "next-router-segment-prefetch", "next-router-state-tree", "next-url"];

// Requests no page answers (app links checks, scanners): a plain 404 without starting the app
const JUNK = /^\/(\.well-known\/|wp-|wordpress|xmlrpc|cgi-bin|vendor\/|\.env|\.git|phpmyadmin)|\.(php|asp|aspx|jsp|cgi|env|ini|bak|sql)$/i;
// Changes on every successful admin save (see bumpVersion below); read at most every 5 s per isolate
let version = { v: "0", at: 0 };
async function storeVersion(env: Env) {
  if (Date.now() - version.at < 5000) return version.v;
  try {
    const r = await env.DB.prepare(`SELECT "value" FROM "Setting" WHERE "key" = ?`).bind("cache.version").first<{ value: string }>();
    version = { v: r?.value ?? "0", at: Date.now() };
  } catch {
    version = { v: version.v, at: Date.now() };
  }
  return version.v;
}
function cookie(req: Request, name: string) {
  const m = (req.headers.get("cookie") ?? "").match(new RegExp(`(?:^|;\\s*)${name}=([^;]*)`));
  return m ? m[1] : "";
}
async function digest(s: string) {
  const b = new Uint8Array(await crypto.subtle.digest("SHA-1", new TextEncoder().encode(s)));
  return Array.from(b.slice(0, 10), (x) => x.toString(16).padStart(2, "0")).join("");
}
async function bumpVersion(env: Env) {
  await env.DB.prepare(
    `INSERT INTO "Setting" ("key", "value") VALUES ('cache.version', ?) ON CONFLICT("key") DO UPDATE SET "value" = excluded."value"`,
  )
    .bind(String(Date.now()))
    .run();
}
// Admin API handlers read the real method from this header (a read never clears the data cache); any value sent
// by the browser is replaced
function withMethod(req: Request) {
  if (!new URL(req.url).pathname.startsWith("/api/admin/")) return req;
  const headers = new Headers(req.headers);
  headers.set("x-dyllu-method", req.method);
  return new Request(req, { headers });
}
const cacheable = (r: Response) => {
  const t = r.headers.get("content-type") ?? "";
  return (
    (r.status === 200 || r.status === 404) &&
    !r.headers.has("set-cookie") &&
    /^(text\/html|text\/x-component|application\/(xml|manifest\+json|json)|text\/plain)/.test(t)
  );
};

async function edge(req: Request, env: Env, ctx: Ctx): Promise<Response> {
  const url = new URL(req.url);
  const get = req.method === "GET" || req.method === "HEAD";
  const cache = (globalThis.caches as unknown as { default?: Cache } | undefined)?.default;
  if (!get) {
    const res: Response = await app.fetch(withMethod(req), env, ctx);
    // A saved admin change: every edge copy is replaced on its next visit
    if (res.ok && url.pathname.startsWith("/api/admin/") && !/\/(login|logout)$/.test(url.pathname))
      ctx.waitUntil(bumpVersion(env).catch(() => {}));
    return res;
  }
  if (JUNK.test(url.pathname)) return new Response("Not found", { status: 404, headers: { "Cache-Control": "public, max-age=86400" } });
  if (!cache) return app.fetch(req, env, ctx);

  // Uploaded images and files: straight from R2 (the Next.js app is not started), then kept at the edge
  const file = url.pathname.match(/^\/uploads\/([\w-]{4,64}\.(jpg|png|webp|gif|pdf))$/);
  if (file) {
    const key = new Request(url.origin + url.pathname);
    const hit = await cache.match(key);
    if (hit) return hit;
    const obj = await env.BUCKET.get(file[1]);
    if (!obj) return app.fetch(req, env, ctx); // older files still in the database
    const headers = new Headers({
      "Content-Type": obj.httpMetadata?.contentType || TYPES[file[2]] || "application/octet-stream",
      "Content-Length": String(obj.size),
      "Cache-Control": `public, max-age=${FILE_TTL}, immutable`,
      "X-Content-Type-Options": "nosniff",
    });
    const res = new Response(obj.body, { headers });
    ctx.waitUntil(cache.put(key, res.clone()));
    return res;
  }
  const api = CACHED_API.test(url.pathname);
  if (!api && (PRIVATE.test(url.pathname) || url.pathname.startsWith("/_next/"))) return app.fetch(withMethod(req), env, ctx);

  // Signed-in admins always get the live store, so their own changes show at once
  if (cookie(req, "dyllu_admin")) return app.fetch(req, env, ctx);

  // One copy per page, language, wholesale code and router state (client navigation), per deploy.
  // A copy made before the last admin save, or older than PAGE_TTL, is still served immediately while a
  // fresh one is rendered in the background: visitors never wait for a render that already has a copy.
  const variant = [
    cookie(req, "lang") === "en" ? "en" : "ar",
    cookie(req, "dyllu_ws"),
    ...ROUTER_HEADERS.map((h) => req.headers.get(h) ?? ""),
    req.method,
  ].join("|");
  const build = env.CF_VERSION_METADATA?.id ?? "dev";
  const current = await storeVersion(env);
  const key = new Request(`${url.origin}/__page/${build}/${await digest(variant)}${url.pathname}${url.search}`);
  const store = async (res: Response) => {
    if (!cacheable(res)) return;
    const copy = new Response(res.body, res);
    copy.headers.set("Cache-Control", `public, max-age=${KEEP}`);
    copy.headers.set("X-Store-Version", current);
    copy.headers.set("X-Stored-At", String(Date.now()));
    await cache.put(key, copy);
  };
  const hit = await cache.match(key);
  if (hit) {
    const age = Date.now() - Number(hit.headers.get("X-Stored-At") || 0);
    const fresh = hit.headers.get("X-Store-Version") === current && age < (hit.status === 404 ? MISSING_TTL : PAGE_TTL) * 1000;
    if (!fresh && !refreshing.has(key.url)) {
      refreshing.add(key.url);
      ctx.waitUntil(
        app
          .fetch(new Request(req.url, { headers: req.headers }), env, ctx)
          .then(store)
          .catch(() => {})
          .finally(() => refreshing.delete(key.url)),
      );
    }
    const h = new Response(hit.body, hit);
    h.headers.set("Cache-Control", "private, no-cache"); // browsers always ask again; the edge answers
    h.headers.set("X-Edge-Cache", fresh ? "HIT" : "STALE");
    h.headers.delete("X-Store-Version");
    h.headers.delete("X-Stored-At");
    return h;
  }
  const res: Response = await app.fetch(req, env, ctx);
  ctx.waitUntil(store(res.clone()).catch(() => {}));
  return res;
}

export default {
  async fetch(req: Request, env: Env, ctx: Ctx) {
    // The schedule's key is only ever added by scheduled() below
    if (req.headers.has("x-dyllu-cron")) {
      const headers = new Headers(req.headers);
      headers.delete("x-dyllu-cron");
      req = new Request(req, { headers });
    }
    try {
      return await edge(req, env, ctx);
    } catch (e) {
      console.error("edge cache", e);
      return app.fetch(req, env, ctx);
    }
  },
  async scheduled(event: { cron?: string }, env: Env, ctx: Ctx) {
    if (event.cron === "17 * * * *") ctx.waitUntil(runUsageAlert(env).catch((e) => console.error("usage alert", e)));
    // Every 5 minutes: notifications for offers and ads whose start time has come, and unfinished sends
    const secret = env.ADMIN_SESSION_SECRET?.trim();
    if (event.cron !== "17 * * * *" && secret) {
      const url = `https://${env.MAIN_DOMAIN || "dyllusa.com"}/api/push/cron`;
      ctx.waitUntil(
        Promise.resolve(app.fetch(new Request(url, { method: "POST", headers: { "x-dyllu-cron": secret } }), env, ctx))
          .then((r: Response) => r.text())
          .catch((e: unknown) => console.error("push schedule", e)),
      );
    }
  },
};
